INSERT INTO package_questions (package_id, question_json, order_index, status) VALUES 
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 42 anos, submetido a apendicectomia videolaparoscópica por apendicite aguda fase III, apresenta febre de 38,4°C e dor em hipocôndrio direito no 7º DPO. Refere também soluços persistentes e dor referida no ombro direito. Ao exame físico: abdome doloroso à palpação profunda em quadrante superior direito, sem massas. Ultrassonografia mostra coleção líquida de 5 cm entre o fígado e o diafragma. Qual a melhor abordagem terapêutica inicial para este abscesso subfrênico?", "options": {"a": "Punção e drenagem percutânea guiada por imagem associada a antibioticoterapia.", "b": "Laparotomia ampla para lavagem exaustiva da cavidade abdominal.", "c": "Expectante apenas com antibioticoterapia de amplo espectro por 14 dias.", "d": "Realizar nova videolaparoscopia para drenagem e biópsia da parede do abscesso.", "e": "Drenagem biliar externa por suspeita de fístula biliar associada."}, "answer": "a", "rationale": "Abscessos intra-abdominais pós-operatórios, quando acessíveis e sem sinais de peritonite generalizada, devem ser preferencialmente tratados com drenagem percutânea guiada por imagem (USG ou TC), por ser menos invasiva e altamente eficaz.", "option_rationales": {"a": "Correta. É o tratamento de escolha inicial para abscessos localizados e acessíveis.", "b": "Incorreta. Muito invasiva para uma coleção localizada que pode ser resolvida por punção.", "c": "Incorreta. Coleções > 3-4 cm raramente resolvem apenas com antibióticos.", "d": "Incorreta. A laparoscopia pode ser uma opção, mas a percutânea é menos traumática e preferível como primeiro passo.", "e": "Incorreta. Não há evidência clínica ou laboratorial de fístula biliar pós-apendicectomia."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Abscesso Abdominal", "Infecção"]}', 21, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente de 75 anos, submetido a prostatectomia radical, apresenta-se no 4º DPO com quadro de desorientação, agitação psicomotora e inversão do ciclo sono-vigília. Não apresenta febre, dor ou sinais de infecção. Os exames laboratoriais mostram Sódio sérico de 132 mEq/L (pré-operatório de 140 mEq/L). O paciente recebeu grande volume de cristaloides no perioperatório. Qual a provável causa do delirium e a conduta recomendada?", "options": {"a": "AVC isquêmico agudo; solicitar angiotomografia de crânio urgente.", "b": "Hiponatremia dilucional; restrição hídrica e monitorização do sódio.", "c": "Demência senil de início abrupto; iniciar memantina.", "d": "Infecção urinária urinosa; iniciar ceftriaxona.", "e": "Insuficiência arterial periférica; realizar Doppler de carótidas."}, "answer": "b", "rationale": "A hiponatremia é uma causa comum de alterações do estado mental em idosos no pós-operatório (envelopamento cirúrgico de sódio ou reposição excessiva com soluções hipotônicas). A correção deve ser cautelosa para evitar síndrome de desmielinização osmótica.", "option_rationales": {"a": "Incorreta. No AVC, geralmente haveria sinais focais (hemiparesia, assimetria facial), o que não foi descrito.", "b": "Correta. A queda do sódio explica a desorientação e a agitação (delirium metabólico).", "c": "Incorreta. Demência não surge de forma aguda; o quadro agudo é Delirium.", "d": "Incorreta. Embora seja um diferencial, a hiponatremia documentada é a causa mais provável e imediata.", "e": "Incorreta. Sem relação direta com o quadro de agitação aguda pulmonar/sistêmica."}, "difficulty": "media", "tags": ["Geriátria", "Pós-operatório", "Hiponatremia", "Delirium"]}', 22, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Uma paciente de 30 anos, submetida a cesariana sob anestesia raquidiana, queixa-se de cefaleia frontal e occipital intensa no 2º DPO. A dor piora significativamente quando a paciente se senta ou fica em pé e alivia quase completamente ao deitar-se (posição supina). Não apresenta febre ou rigidez de nuca. Qual o diagnóstico e a conduta inicial para esta complicação anestésica?", "options": {"a": "Meningite química; punção lombar diagnóstica.", "b": "Cefaleia pós-punção dural (CPPD); repouso, hidratação e cafeína.", "c": "Enxaqueca tensional; uso de sumatriptano.", "d": "Hemorragia subaracnóidea perioperatória; TC de crânio.", "e": "Pré-eclâmpsia pós-parto; sulfato de magnésio."}, "answer": "b", "rationale": "A característica postural da dor (piora ao levantar) é o sinal clássico da cefaleia pós-raqui, causada pelo extravasamento de líquor pelo orifício da punção.", "option_rationales": {"a": "Incorreta. Meningite apresentaria sinais de irritação meníngea e febre.", "b": "Correta. Diagnóstico clínico e manejo inicial conservador.", "c": "Incorreta. Enxaqueca não tem essa variação postural tão marcada.", "d": "Incorreta. Teria início súbito (em trovão) e não aliviaria ao deitar.", "e": "Incorreta. Associada a hipertensão e proteinúria, não descritos."}, "difficulty": "facil", "tags": ["Anestesiologia", "Pós-operatório", "CPPD", "Cefaleia Postural"]}', 23, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório imediato de uma cirurgia de grande porte sob anestesia geral, um paciente apresenta saturação de oxigênio de 85% e hipercapnia (EtCO2 de 55 mmHg) na sala de recuperação pós-anestésica. Ao ser estimulado verbalmente, ele abre os olhos, mas logo volta a dormir. A musculatura apresenta certo grau de fraqueza à manobra de preensão palmar. Qual a causa mais provável da hipoventilação?", "options": {"a": "Choque anafilático tardio.", "b": "Bloqueio neuromuscular residual (curarização residual).", "c": "Efeito excessivo da atropina.", "d": "Pneumotórax bilateral.", "e": "Infarto agudo do miocárdio silencioso."}, "answer": "b", "rationale": "A falha na reversão completa dos bloqueadores neuromusculares adespolarizantes (bloqueio residual) é uma causa frequente de hipoventilação e dessaturação na SRPA.", "option_rationales": {"a": "Incorreta. Anafilaxia teria manifestações cutâneas ou broncospasmo severo.", "b": "Correta. A fraqueza muscular e sonolência são típicas da curarização residual.", "c": "Incorreta. Atropina é um anticolinérgico, não causa depressão respiratória direta.", "d": "Incorreta. Causaria dor e redução bilateral do murmúrio, sem relação direta com o nível de consciência.", "e": "Incorreta. Embora o IAM possa causar hipóxia por edema, a fraqueza muscular focalizada após anestesia aponta para bloqueio residual."}, "difficulty": "media", "tags": ["Anestesiologia", "Pós-operatório", "Bloqueio Neuromuscular", "SRPA"]}', 24, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a tireoidectomia total nas últimas 24h evolui com parestesia perioral e nas pontas dos dedos, além de espasmos musculares dolorosos no antebraço após a insuflação do manguito de pressão arterial. Estes sinais são conhecidos como:", "options": {"a": "Sinais de Chvostek e Trousseau, indicativos de hipocalcemia.", "b": "Sinais de Murphy e Blumberg, indicativos de peritonite superior.", "c": "Sinais de Cullen e Grey-Turner, indicativos de pancreatite.", "d": "Sinais de Homans e Bancroft, indicativos de TVP.", "e": "Sinais de Kernig e Brudzinski, indicativos de meningite."}, "answer": "a", "rationale": "A hipocalcemia aguda (por isquemia ou remoção das paratireoides) causa hiperexcitabilidade neuromuscular. O sinal de Chvostek (contração facial ao percutir o nervo facial) e o de Trousseau (espasmo carpal ao insuflar o manguito) são clássicos.", "option_rationales": {"a": "Correta. Semiologia clássica da hipocalcemia pós-operatória.", "b": "Incorreta. Referem-se ao abdome.", "c": "Incorreta. Referem-se a manchas equimóticas abdominais/flancos.", "d": "Incorreta. Referem-se a trombose venosa de membros inferiores.", "e": "Incorreta. Referem-se a irritação meníngea."}, "difficulty": "facil", "tags": ["Cirurgia Endócrina", "Pós-operatório", "Hipocalcemia", "Semiologia"]}', 25, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um homem de 55 anos, obeso e hipertenso, submetido a gastrostomia cirúrgica devido a neoplasia de esôfago obstrutiva. No 10º DPO, nota-se que a ferida operatória apresenta-se com bordas edemaciadas, hiperemia que se estende por 5 cm além da incisão, calor local e dor intensa à palpação. Não há saída de secreção purulenta ou deiscência. O paciente está afebril. Qual o diagnóstico e o agente etiológico mais comumente envolvido?", "options": {"a": "Celulite de parede abdominal; Staphylococcus aureus.", "b": "Fascite necrosante; Clostridium perfringens.", "c": "Abscesso subcutâneo; Bacteroides fragilis.", "d": "Hérnia incisional infectada; Escherichia coli.", "e": "Reação alérgica ao fio de sutura; sem agente etiológico."}, "answer": "a", "rationale": "A descrição clínica de hiperemia profunda, calor e edema sem coleção purulenta visível sugere celulite (Infecção de Sítio Cirúrgico Incisional Superficial). O S. aureus é o principal colonizador da pele e causa frequente dessas infecções.", "option_rationales": {"a": "Correta. Diagnóstico clínico e agente mais provável para infecção cutânea.", "b": "Incorreta. Fascite teria sinais de necrose, bolhas ou crepitação e evolução tóxica rápida.", "c": "Incorreta. Abscesso exigiria a presença de flutuação e secreção purulenta.", "d": "Incorreta. Não há relato de abaulamento herniário.", "e": "Incorreta. Reação ao fio costuma ser mais localizada e granulomatosa, sem sinais de celulite extensa."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "ISC", "Infecção"]}', 26, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em uma cirurgia abdominal laparotômica prolongada, o uso de afastadores mecânicos fixos por tempo excessivo pode causar uma complicação neurológica periférica específica, manifestada por fraqueza na extensão da perna e perda de sensibilidade na face anterior da coxa. Qual o nervo provavelmente comprimido?", "options": {"a": "Nervo Ciático.", "b": "Nervo Femoral.", "c": "Nervo Obturador.", "d": "Nervo Fibular Comum.", "e": "Nervo Pudendo."}, "answer": "b", "rationale": "O nervo femoral passa sob o ligamento inguinal e pode ser comprimido por afastadores auto-estáticos (ex: afastador de Balfour ou Bookwalter) colocados na parede abdominal profunda.", "option_rationales": {"a": "Incorreta. O ciático é comprimido por posicionamento em litotomia prolongada.", "b": "Correta. Lesão clássica associada a afastadores abdominais.", "c": "Incorreta. Nervo obturador causaria dor na face medial da coxa.", "d": "Incorreta. Nervo fibular causaria pé caído (compressão na cabeça da fíbula).", "e": "Incorreta. Nervo pudendo não tem função motora em coxa."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Lesão Nervosa", "Complicações Técnicas"]}', 27, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 60 anos, em 2º DPO de uma cirurgia de correção de aneurisma de aorta abdominal eletiva, apresenta-se com dor abdominal intensa, diarreia muco-sanguinolenta e leucocitose importante (22.000/mm³). Ao exame físico, apresenta certa distensão e dor à palpação profunda em flanco esquerdo. Qual a complicação isquêmica mais temida após este tipo de procedimento?", "options": {"a": "Isquemia mesentérica superior embólica.", "b": "Isquemia colônica (Colite Isquêmica) por ligadura da artéria mesentérica inferior.", "c": "Infarto esplênico por manipulação do pedículo.", "d": "Trombose de artérias renais bilateral.", "e": "Apendicite isquêmica retrógrada."}, "answer": "b", "rationale": "A ligadura da artéria mesentérica inferior é frequentemente necessária na correção de aneurismas de aorta. Se a circulação colateral via arcada de Riolan for insuficiente, ocorre isquemia colônica, tipicamente do sigmoide.", "option_rationales": {"a": "Incorreta. A AMS raramente é afetada; o quadro clínico de diarreia precoce aponta para o cólon descendente/sigmoide.", "b": "Correta. Complicação clássica da cirurgia de aorta abdominal.", "c": "Incorreta. Baço não é suprido pela mesentérica inferior.", "d": "Incorreta. Renal causaria anúria/oligúria, não diarreia sanguinolenta.", "e": "Incorreta. Não existe este termo diagnóstico clínico padrão."}, "difficulty": "dificil", "tags": ["Cirurgia Vascular", "Pós-operatório", "Isquemia Colônica", "Aneurisma"]}', 28, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal medida preventiva para evitar a ocorrência de NTA (Necrose Tubular Aguda) no pós-operatório de pacientes submetidos a cirurgia cardíaca com CEC prolongada ou cirurgias com grande perda volêmica?", "options": {"a": "Uso rotineiro de dopamina em ''dose renal''.", "b": "Manutenção de débito cardíaco e pressão de perfusão adequados com reposição volêmica guiada por metas.", "c": "Administração de furosemida endovenosa preventiva para manter diurese > 2 ml/kg/h.", "d": "Uso de manitol profilático antes do clampeamento da aorta.", "e": "Restrição hídrica severa para evitar congestão renal."}, "answer": "b", "rationale": "A manutenção da perfusão tecidual e do fluxo sanguíneo renal é a melhor estratégia contra a insuficiência renal aguda. Otimizar a oferta de oxigênio (DO2) é superior ao uso de drogas nefroprotetoras míticas.", "option_rationales": {"a": "Incorreta. Dopamina em dose renal não tem evidência científica de benefício protetor.", "b": "Correta. Pilar da terapia de suporte intensivo perioperatório.", "c": "Incorreta. Diuréticos podem transformar uma falência renal oligúrica em não-oligúrica, mas não previnem a lesão em si e podem piorar o status volêmico.", "d": "Incorreta. Uso controverso e sem evidência robusta de proteção na maioria dos cenários.", "e": "Incorreta. Hipovolemia é um dos principais gatilhos da NTA pré-renal e renal."}, "difficulty": "media", "tags": ["Terapia Intensiva", "Pós-operatório", "IRA", "Prevenção"]}', 29, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 40 anos, diagnosticado com Doença de Crohn, foi submetido a uma enterectomia segmentar. No 15º DPO, apresenta-se com drenagem persistente de conteúdo entérico (cerca de 300 ml/dia) por um dos orifícios dos pontos da pele. Não há sinais de peritonite. Com base no diagnóstico de fístula enterocutânea de médio débito, qual o primeiro passo no manejo nutricional?", "options": {"a": "Iniciar dieta oral rica em fibras para estimular o trânsito.", "b": "Manter jejum oral e iniciar Nutrição Parenteral Total (NPT) para promover o ''repouso'' intestinal.", "c": "Instalar sonda nasogástrica em aspiração contínua e manter dieta hipoproteica.", "d": "Realizar laparotomia imediata para fechamento da fístula e reforço com tela.", "e": "Substituir a dieta parenteral por dieta enteral elementar imediata."}, "answer": "b", "rationale": "O manejo inicial das fístulas entéricas envolve: Estabilização (fluidez/eletrólitos), Controle da infecção, Proteção da pele e Suporte nutricional. A NPT é frequentemente necessária para garantir aporte calórico enquanto o intestino repousa, reduzindo o débito da fístula.", "option_rationales": {"a": "Incorreta. Dieta oral aumentaria o débito e impediria a cicatrização espontânea.", "b": "Correta. Estratégia padrão para fístulas de delgado.", "c": "Incorreta. Dieta hipoproteica prejudica a cicatrização.", "d": "Incorreta. A cirurgia precoce (fase inflamatória) tem altíssimo índice de falha e novas fístulas.", "e": "Incorreta. Enteral pode ser tentada se a fístula for distal e a sonda passar o óstio, mas a NPT é o passo inicial mais seguro em fístulas altas de médio/alto débito."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "Fístula Enterocutânea", "Nutrição Cirúrgica"]}', 30, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A infecção urinária (ITU) é uma das complicações mais comuns no pós-operatório hospitalar. Qual o principal fator de risco modificável associado a esta condição em pacientes cirúrgicos?", "options": {"a": "Tipo de antibiótico profilático usado na indução.", "b": "Tempo de permanência do cateter vesical de demora (sonda de Foley).", "c": "Uso de anestesia raquidiana.", "d": "Posição do paciente na mesa de operação.", "e": "Idade avançada do paciente."}, "answer": "b", "rationale": "A duração da cateterização vesical é o fator de risco mais importante para bacteriúria e infecção urinária sintomática. Recomenda-se a retirada em 24-48h pós-op, se possível.", "option_rationales": {"a": "Incorreta. Profilaxia cirúrgica visa evitar infecção do sítio cirúrgico, não ITU.", "b": "Correta. Fator de risco número 1 em ambiente hospitalar.", "c": "Incorreta. Raqui pode causar retenção, mas a infecção vem do cateter.", "d": "Incorreta. Sem relação direta.", "e": "Incorreta. É um fator de risco, mas não é modificável."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "ITU", "Segurança do Paciente"]}', 31, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No 3º DPO de uma lobectomia pulmonar direita, um paciente apresenta-se subitamente agitado, com sudorese, taquicardia e distensão abdominal. O murmúrio vesicular está ausente à direita com hipertimpanismo à percussão. A traqueia está desviada para a esquerda. Qual a conduta imediata antes de qualquer exame de imagem?", "options": {"a": "Realizar toracocentese de alívio no 2º espaço intercostal na linha hemiclavicular ou 4º/5º espaço na linha axilar anterior.", "b": "Solicitar radiografia de tórax em PA e Perfil urgente.", "c": "Introduzir sonda nasogástrica para descompressão gástrica.", "d": "Realizar ECG para descartar IAM.", "e": "Instalar ventilação mecânica com pressão positiva (VPP)."}, "answer": "a", "rationale": "O quadro é típico de pneumotórax hipertensivo, uma emergência que exige diagnóstico clínico imediato e descompressão por agulha ou dreno antes da imagem, pois o atraso pode levar ao choque obstrutivo e parada cardíaca.", "option_rationales": {"a": "Correta. Manobra de salvamento imediata.", "b": "Incorreta. O tempo para o raio-x pode ser fatal no pneumotórax hipertensivo.", "c": "Incorreta. Não resolve a compressão intratorácica.", "d": "Incorreta. Diagnóstico clínico de PTX é soberano neste caso.", "e": "Incorreta. VPP pode piorar o pneumotórax se o dreno não estiver funcionante."}, "difficulty": "media", "tags": ["Cirurgia Torácica", "Pós-operatório", "Pneumotórax", "Emergência"]}', 32, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente submetido a gastroduodenopancreatectomia (Whipple). No 2º DPO, o dreno abdominal exterioriza 800 ml de sangue rutilante nas últimas 2 horas, associado a queda de pressão e taquicardia. O diagnóstico de hemorragia pós-operatória precoce é feito. Além da reposição volêmica, qual a conduta imediata para este paciente?", "options": {"a": "Apenas observar e transfundir 2 unidades de sangue.", "b": "Inspecionar a ferida e realizar compressão local.", "c": "Reoperação imediata (Laparotomia) para revisão de hemostasia.", "d": "Solicitar tomografia com contraste daqui a 12 horas.", "e": "Iniciar infusão de omeprazol em altas doses."}, "answer": "c", "rationale": "Hemorragia precoce (< 24-48h) com instabilidade hemodinâmica após cirurgia de grande porte é geralmente causada por falha técnica de hemostasia (desprendimento de ligadura ou sangramento de leito) e exige reintervenção cirúrgica imediata.", "option_rationales": {"a": "Incorreta. Conduta perigosa em sangramento de alto débito e ativo.", "b": "Incorreta. O sangramento é interno (cavidade), a compressão externa da ferida não ajuda.", "c": "Correta. Padrão para hemorragia pós-op hemodinamicamente instável.", "d": "Incorreta. Exame de imagem retarda o tratamento definitivo em paciente instável.", "e": "Incorreta. Omeprazol não trata sangramento arterial cirúrgico."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Hemorragia", "Emergência"]}', 33, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Qual a principal causa metabólica de íleo adinâmico prolongado no pós-operatório que deve ser sempre checada e corrigida antes de se considerar reintervenção?", "options": {"a": "Hipernatremia.", "b": "Hipocalemia (baixos níveis de potássio).", "c": "Hipercalcemia.", "d": "Hipotireoidismo.", "e": "Hipoglicemia."}, "answer": "b", "rationale": "O potássio é fundamental para o potencial de repouso das membranas das células musculares lisas do intestino. A hipocalemia causa paralisia da motilidade intestinal.", "option_rationales": {"a": "Incorreta. Causa sintomas neurológicos predominantemente.", "b": "Correta. Causa metabólica clássica de íleo.", "c": "Incorreta. Hipercalcemia pode causar constipação crônica, mas no pós-op agudo o potássio é mais crítico.", "d": "Incorreta. Muito raro causar íleo agudo sem história de coma mixedematoso.", "e": "Incorreta. Sem relação direta com motilidade."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Íleo Adinâmico", "Eletrólitos"]}', 34, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 48 anos, no 5º DPO de uma colecistectomia aberta, apresenta dor em panturrilha direita. O Doppler venoso confirma TVP de veias poplítea e femoral. A paciente possui histórico de úlcera gástrica sangrante há 1 mês, tendo sido tratada com endoscopia e clipagem. De acordo com as diretrizes de antitrombóticos, qual a melhor estratégia inicial?", "options": {"a": "Fibrinólise por cateter visando lise do trombo.", "b": "Filtro de veia cava inferior devido à contraindicação para anticoagulação plena (sangramento digestivo recente).", "c": "Anticoagulação plena com Rivaroxabana oral.", "d": "Anticoagulação com Heparina e Vigilância Endoscópica semanal.", "e": "Apenas deambulação e meia elástica de alta compressão."}, "answer": "b", "rationale": "A presença de sangramento gastrointestinal grave recente (dentro de 4 semanas) é uma contraindicação relativa/absoluta para anticoagulação plena se houver risco de ressangramento fatal. O filtro de veia cava protege o paciente contra TEP sem o risco hemorrágico.", "option_rationales": {"a": "Incorreta. Fibrinólise é ainda mais perigosa que anticoagulação.", "b": "Correta. Indicação clássica de filtro de VCI.", "c": "Incorreta. Risco de ressangramento da úlcera gástrica recente.", "d": "Incorreta. Vigilância não impede o sangramento induzido pela heparina.", "e": "Incorreta. Insuficiente para prevenir embolia pulmonar."}, "difficulty": "moderada", "tags": ["Cirurgia Vascular", "Pós-operatório", "TVP", "Segurança"]}', 35, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No pós-operatório de uma lobectomia de tireoide por carcinoma papilífero, observa-se que o paciente apresenta rouquidão persistente e incapacidade de atingir tons agudos ao cantar. Ao exame de laringoscopia indireta, a prega vocal ipsilateral movimenta-se normalmente, mas está flácida e levemente encurtada. Qual o nervo lesionado?", "options": {"a": "Nervo Laríngeo Recorrente.", "b": "Ramo externo do Nervo Laríngeo Superior.", "c": "Nervo Hipoglosso.", "d": "Nervo Vago (tronco principal).", "e": "Nervo Glossofaríngeo."}, "answer": "b", "rationale": "A lesão do ramo externo do nervo laríngeo superior causa paralisia do músculo cricotireóideo, responsável por tensionar as pregas vocais para notas agudas. A voz fica ''cansada'' e sem alcance agudo, mas a mobilidade da prega (fechamento/abertura) é preservada.", "option_rationales": {"a": "Incorreta. Lesão do recorrente causaria paralisia da prega vocal, levando a soprosidade e risco de aspiração.", "b": "Correta. Lesão clássica associada à ligadura da artéria tireoidiana superior.", "c": "Incorreta. Causaria desvio da língua.", "d": "Incorreta. Causaria paralisia completa do palácio e pregas vocais.", "e": "Incorreta. Alteraria o reflexo do vômito e sensibilidade do palato posterior."}, "difficulty": "moderada", "tags": ["Cirurgia de Cabeça e Pescoço", "Pós-operatório", "Lesão Nervosa", "Tireoide"]}', 36, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 60 anos, em 12º DPO de uma gastrectomia subtotal, apresenta dor em hipocôndrio direito, icterícia leve e febre. Ultrassonografia mostra vesícula biliar distendida, com parede espessada (> 4mm) e líquido pericolecístico, sem evidência de cálculos ou lama biliar. Qual o diagnóstico provável para esta complicação associada ao jejum prolongado e nutrição parenteral?", "options": {"a": "Colecistite alitiásica pós-operatória.", "b": "Coledocolitíase residual por cálculo não visto.", "c": "Hepatite medicamentosa induzida por opioides.", "d": "Síndrome de Mirizzi aguda.", "e": "Colangite esclerosante primária de início súbito."}, "answer": "a", "rationale": "A colecistite alitiásica é uma complicação grave em pacientes de UTI ou pós-operatórios prolongados, favorecida pela estase biliar (falta de estímulo de colecistocinina pelo jejum) e isquemia da parede da vesícula.", "option_rationales": {"a": "Correta. Quadro clínico típico de colecistite sem cálculos em paciente crítico.", "b": "Incorreta. Não há cálculos na imagem.", "c": "Incorreta. Opioides não costumam causar imagem de colecistite.", "d": "Incorreta. Exige cálculo no duto cístico comprimindo o colédoco.", "e": "Incorreta. Doença crônica autoimune, não se manifesta desta forma aguda."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Colecistite Alitiásica", "Biliar"]}', 37, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Paciente de 40 anos, com história de alcoolismo ocasional, é submetido a necrosectomia pancreática por pancreatite grave. No 20º DPO, apresenta hemorragia volumosa subitamente pelo dreno abdominal colocado na loja pancreática, associada a choque hemorrágico. Qual a complicação vascular mais provável após cirurgia ou inflamação pancreática severa?", "options": {"a": "Ruptura de varizes esofágicas.", "b": "Hemorragia digestiva alta por úlcera de estresse (Dieulafoy).", "c": "Erosão e ruptura de pseudoaneurisma de artéria peripancreática (ex: Artéria Esplênica).", "d": "Fístula aorto-entérica.", "e": "Sangramento venoso por trombose da veia cava inferior."}, "answer": "c", "rationale": "As fístulas e abscessos pancreáticos são ricos em enzimas proteolíticas que podem erodir a parede das artérias adjacentes (esplênica, gastroduodenal), formando pseudoaneurismas que, ao romperem, causam sangramentos catastróficos.", "option_rationales": {"a": "Incorreta. O sangramento é pelo dreno abdominal, não pela boca (hematêmese).", "b": "Incorreta. Mesma justificativa da anterior.", "c": "Correta. Complicação vascular tardia clássica da pancreatite infectada/necrosectomia.", "d": "Incorreta. Geralmente associada a próteses de aorta ou úlceras de aorta em D3 do duodeno.", "e": "Incorreta. Sangramento venoso costuma ser menos dramático e rápido que o observado."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Pâncreas", "Pseudoaneurisma"]}', 38, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No manejo de uma ferida operatória com suspeita de Infecção de Sítio Cirúrgico de Órgão/Espaço (ex: peritonite residual), qual o exame de imagem padrão-ouro para o diagnóstico e eventual planejamento de drenagem?", "options": {"a": "Radiografia de abdome em 3 posições.", "b": "Ultrassonografia de parede abdominal.", "c": "Tomografia Computadorizada de abdome e pelve com contraste endovenoso.", "d": "Pielografia retrógrada.", "e": "Endoscopia digestiva alta."}, "answer": "c", "rationale": "A TC com contraste é o melhor exame para identificar coleções profundas, abscessos e deiscências de anastomose, permitindo visualizar a anatomia e planejar o acesso cirúrgico ou percutâneo.", "option_rationales": {"a": "Incorreta. Pouco sensível para coleções líquidas.", "b": "Incorreta. Útil para parede, mas perde acurácia em coleções profundas devido ao gás intestinal.", "c": "Correta. Exame de escolha para complicações intra-abdominais.", "d": "Incorreta. Exame das vias urinárias.", "e": "Incorreta. Avalia apenas o lúmen, não o espaço extraluminal."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Diagnóstico", "TC"]}', 39, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A ocorrência de ''serosidade'' (secreção límpida, cor de palha) abundante em ferida operatória, associada a desconforto local exagerado no 5º-7º DPO, deve alertar o cirurgião para o início de qual processo de deiscência?", "options": {"a": "Infecção por Streptococcus pyogenes.", "b": "Deiscência da aponeurose (Evisceração iminente).", "c": "Cicatrização por segunda intenção saudável.", "d": "Hematoma em fase de liquefação.", "e": "Fístula linfática pura."}, "answer": "b", "rationale": "O líquido serossanguinolento maciço (''água de carne'') é o precursor da deiscência aponeurótica. A dor e o volume de secreção indicam que a sutura profunda rompeu e o líquido peritoneal está vazando.", "option_rationales": {"a": "Incorreta. Infecção teria pus e sinais flogísticos.", "b": "Correta. Sinal clínico clássico de deiscência profunda.", "c": "Incorreta. A saída abundante de líquido não é parte do processo normal saudável.", "d": "Incorreta. Hematoma seria mais escuro e coaculado.", "e": "Incorreta. Linfa é límpida mas raramente tão abundante e associada a dor de ferida laparotômica."}, "difficulty": "media", "tags": ["Cirurgia Geral", "Pós-operatório", "Deiscência", "Parede Abdominal"]}', 40, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente de 35 anos, submetido a apendicectomia incidental durante cirurgia ginecológica, desenvolve febre de 38,8°C e dor abdominal no 1º DPO. O cirurgião suspeita de infecção por clostrídios ou estreptococo do grupo A (ISC agressiva). Qual característica da secreção local e rapidez de evolução sugere este tipo de infecção necrotizante precoce?", "options": {"a": "Pus espesso e amarelado acumulado há 3 dias.", "b": "Secreção serossanguinolenta (líquida) e sinais de toxicidade sistêmica em menos de 24 horas do procedimento.", "c": "Saída de fezes pelo dreno no 7º dia.", "d": "Pele fria e pálida ao redor dos pontos.", "e": "Aparecimento de prurido e placas urticadas."}, "answer": "b", "rationale": "Infecções agressivas por GAS ou Clostridium ocorrem muito precocemente (< 24h) e raramente formam pus franco inicialmente; a secreção é rala e o paciente evolui rapidamente para choque séptico.", "option_rationales": {"a": "Incorreta. Isso sugere S. aureus ou infecção mista tardia.", "b": "Correta. Características da fascite necrotizante ou ISC tóxica.", "c": "Incorreta. Sugere deiscência de anastomose tardia.", "d": "Incorreta. Sem nexo com infecção aguda agressiva.", "e": "Incorreta. Sugere alergia."}, "difficulty": "moderada", "tags": ["Cirurgia Geral", "Pós-operatório", "ISC", "Fascite Necrosante"]}', 41, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "A principal causa de febre no pós-operatório IMEDIATO (primeiras 24 horas), na ausência de sinais clínicos de infecção ou de atelectasias óbvias, costuma ser atribuída a:", "options": {"a": "Infecção urinária hospitalar.", "b": "Pneumonia aspirativa silenciosa.", "c": "Resposta inflamatória sistêmica metabólica ao trauma cirúrgico (citocinas como IL-1, IL-6 e TNF-alfa).", "d": "Uso de contrastes iodados.", "e": "Alimentação gástrica precoce."}, "answer": "c", "rationale": "A febre nas primeiras 24h é frequentemente inflamatória e não infecciosa, refletindo o estresse cirúrgico. Geralmente é autolimitada e benigna.", "option_rationales": {"a": "Incorreta. Muito precoce para infecção bacteriana hospitalar.", "b": "Incorreta. Teria sintomas respiratórios importantes.", "c": "Correta. Mecanismo fisiopatológico da febre precoce fisiológica.", "d": "Incorreta. Causa alergia ou nefrotoxicidade, não febre primária.", "e": "Incorreta. Não tem nexo causal."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "Febre", "Fisiologia"]}', 42, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "No manejo do íleo adinâmico pós-operatório, a diretriz ERAS (Enhanced Recovery After Surgery) recomenda como uma das principais medidas preventivas:", "options": {"a": "Uso abundante de opioides para controle da dor.", "b": "Manter paciente em repouso absoluto no leito até a primeira evacuação.", "c": "Alimentação oral precoce e uso restrito de opioides (priorizando analgesia multimodal).", "d": "Uso rotineiro de sonda nasogástrica até a volta dos ruídos hidroaéreos.", "e": "Hidratação volêmica vigorosa com 5 litros de soro ao dia."}, "answer": "c", "rationale": "O protocolo ERAS visa reduzir o estresse cirúrgico. A alimentação precoce e a redução de opioides (que causam paralisia intestinal) são fundamentais para a rápida recuperação do trânsito.", "option_rationales": {"a": "Incorreta. Opioides pioram o íleo.", "b": "Incorreta. Deambulação precoce é incentivada.", "c": "Correta. Pilares da medicina perioperatória moderna.", "d": "Incorreta. Sonda nasogástrica de rotina aumenta complicações e prolonga o íleo.", "e": "Incorreta. Balanço hídrico zerado/negativo é preferível para evitar edema de alça."}, "difficulty": "facil", "tags": ["Cirurgia Geral", "Pós-operatório", "ERAS", "Íleo Adinâmico"]}', 43, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Em pacientes idosos submetidos a cirurgias pélvicas (ex: ressecção de reto) ou ortopédicas de quadril, qual a complicação não-cirúrgica mais frequente que impacta significativamente o tempo de internação?", "options": {"a": "Catarata agudizada.", "b": "Delirium (Síndrome Confusional Aguda).", "c": "Gengivite hospitalar.", "d": "Hérnia de disco.", "e": "Surdez pós-anestésica."}, "answer": "b", "rationale": "O delirium pós-operatório atinge até 50% dos idosos após grandes cirurgias e está associado a maior morbimortalidade e declínio funcional.", "option_rationales": {"a": "Incorreta.", "b": "Correta. Complicação clínica geriátrica clássica.", "c": "Incorreta.", "d": "Incorreta.", "e": "Incorreta."}, "difficulty": "facil", "tags": ["Geriátria", "Pós-operatório", "Delirium", "Complicações Sistêmicas"]}', 44, 'draft'),
('72dd3eb5-dd9b-409c-8501-f2fdc061140a', '{"enunciado": "Um paciente submetido a cirurgia abdominal por câncer de cólon evolui no 4º DPO com dor panturrilha esquerda. Doppler confirma TVP. No histórico, o paciente tem um Filtro de Veia Cava colocado há 3 meses devido a TEP prévio e contraindicação temporária para anticoagulação. Como deve ser o manejo da TVP neste paciente agora, estando ele estável no pós-operatório?", "options": {"a": "Não precisa de tratamento, pois o filtro protege contra TEP.", "b": "Trocar o dreno abdominal e aguardar.", "c": "Iniciar anticoagulação plena, pois o objetivo do filtro não é tratar o trombo existente, mas apenas evitar a embolia.", "d": "Retirar o filtro imediatamente via cirúrgica.", "e": "Apenas observação clínica rigorosa."}, "answer": "c", "rationale": "O filtro de veia cava não trata a trombose nem previne a extensão do trombo; ele apenas ''filtra'' grandes êmbolos. Se o paciente não tiver mais contraindicação hemorrágica, a anticoagulação deve ser iniciada para tratar a TVP.", "option_rationales": {"a": "Incorreta. O filtro não impede o crescimento do trombo na perna ou síndrome pós-trombótica.", "b": "Incorreta. Sem relação.", "c": "Correta. Manejo da TVP em vigência de filtro.", "d": "Incorreta. Filtros podem ser permanentes ou recuperáveis, mas não são retirados no momento de uma TVP aguda.", "e": "Incorreta. TVP exige tratamento ativo."}, "difficulty": "media", "tags": ["Cirurgia Vascular", "Pós-operatório", "TVP", "Filtro de VCI"]}', 45, 'draft')
